function makeAsphalt() {
  const S=1024;
  const c=document.createElement('canvas'); c.width=c.height=S;
  const x=c.getContext('2d');
  x.fillStyle='#171b1d'; x.fillRect(0,0,S,S);
  const rng=mulberry32(1234);
  // broad wet patches
  for(let i=0;i<40;i++){
    const px=rng()*S, py=rng()*S, r=40+rng()*180;
    const g=x.createRadialGradient(px,py,0,px,py,r);
    const light = rng()>0.5;
    g.addColorStop(0, light?'rgba(70,78,82,0.10)':'rgba(0,0,0,0.20)');
    g.addColorStop(1,'rgba(0,0,0,0)');
    x.fillStyle=g; x.fillRect(0,0,S,S);
  }
  // streaks along y
  for(let i=0;i<2600;i++){
    const px=rng()*S, py=rng()*S, len=8+rng()*90;
    x.strokeStyle='rgba('+(rng()>0.5?90:10)+','+(rng()>0.5?98:12)+','+(rng()>0.5?102:14)+','+(0.02+rng()*0.05)+')';
    x.lineWidth=0.5+rng()*2.5;
    x.beginPath(); x.moveTo(px,py); x.lineTo(px+(rng()-0.5)*4,py+len); x.stroke();
  }
  // speckle
  ...
  const map=new THREE.CanvasTexture(c);
  map.wrapS=map.wrapT=THREE.RepeatWrapping; map.repeat.set(4,24); map.colorSpace=THREE.SRGBColorSpace; map.anisotropy=maxAniso;

  // roughness canvas 512
  ...
  // normal canvas from height
}
```

