cat > /tmp/shot.cjs <<'EOF'
const path = process.argv[2];
const times = process.argv[3].split(',').map(Number);
const outdir = process.argv[4] || '/tmp/shots';
const { chromium } = require(path);
(async () => {
  const browser = await chromium.launch({ args: ['--enable-unsafe-swiftshader','--use-angle=swiftshader','--disable-gpu-sandbox','--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
  page.on('console', m => { if (m.type()==='error') console.error('PAGE:', m.text()); });
  page.on('pageerror', e => console.error('PAGEERR:', e.message));
  const t0=Date.now();
  await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load', timeout: 120000 });
  await page.waitForFunction(() => !!window.__filmTimeline, null, { timeout: 120000 });
  console.log('loaded in', Date.now()-t0,'ms');
  const fs = require('fs');
  if (!fs.existsSync(outdir)) fs.mkdirSync(outdir, { recursive: true });
  for (const t of times) {
    const s=Date.now();
    const state = await page.evaluate((tt) => {
      window.__filmTimeline.pause();
      window.__filmTimeline.seek(tt, false);
      return { t: window.__filmTimeline.time(), play: window.__film ? window.__film.renderAt ? 'ok' : 'no' : 'none' };
    }, t);
    await page.evaluate((tt)=>{ if(window.__film) window.__film.renderAt(tt); }, t);
    await page.waitForTimeout(80);
    const fn = `${outdir}/t_${String(t).replace('.','_')}.png`;
    await page.screenshot({ path: fn });
    console.log('shot', t, 'timeline', state.t, 'in', Date.now()-s,'ms', fn);
  }
  await browser.close();
})();
EOF
